-- ----------------------------
-- Table structure for vs_about
-- ----------------------------
DROP TABLE IF EXISTS `vs_about`;
CREATE TABLE `vs_about`  (
  `about` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `id` int NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of vs_about
-- ----------------------------
INSERT INTO `vs_about` VALUES ('<h1>Our Mission = Big Brands - Low Prices</h1>\n\n<p>At&nbsp;<strong>MandM Direct</strong>&nbsp;we&rsquo;re proud to be different.</p>\n\n<p>We want to give you the biggest brands at the lowest prices you&#39;ll find.</p>\n\n<p><strong>How do we do it?</strong></p>\n\n<p>The answer is simple - we buy directly from brands, licensees and suppliers.</p>\n\n<p>Just like you, we&#39;re always hunting for a bargain.</p>\n\n<p>Our buyers are always looking for opportunities to buy&nbsp;<strong>quality brands</strong>&nbsp;and&nbsp;<strong>on-trend Clothing, Footwear &amp; Accessories.</strong>&nbsp;Over time we&#39;ve built long-term relationships with many companies and currently&nbsp;<strong>stock over 150 brands</strong>, ranging from big household names to up-and-coming labels.</p>\n\n<p>Still wondering how our prices are so low? Find out more in our&nbsp;<a href=\"https://www.mandmdirect.com/01/landing/blog-190607-cheap-guide\">MandM Direct: How are we so cheap?</a>&nbsp;blog post.</p>\n\n<h1>Our Story</h1>\n\n<p><strong>Our journey</strong>&nbsp;began in&nbsp;<strong>1987</strong>&nbsp;by selling end of line sports products directly to customers in the UK. Now more than&nbsp;<strong>30 years on</strong>, we&#39;re one of Europe&#39;s leading online off-price retailers with&nbsp;<strong>over 3 million active customers</strong>. We also have numerous dedicated local market websites across Europe and deliver to&nbsp;<a href=\"https://www.mandmdirect.com/01/landing/countryselect\">25+ countries worldwide.</a></p>\n\n<p>In&nbsp;<strong>2014</strong>&nbsp;MandM Direct Ltd was purchased by Danish fashion group&nbsp;<strong>Bestseller</strong>. Bestseller is owned and run by&nbsp;<strong>Anders Holch Povlsen</strong>, after inheriting the business from his parents. Anders has grown Bestseller into one of the largest companies in the fashion retail industry.</p>\n\n<p><strong>Our success</strong>&nbsp;is down to our commitment and passion for seeking out the biggest&nbsp;<strong>Fashion, Sport</strong>&nbsp;and&nbsp;<strong>Outdoor</strong>&nbsp;brands and giving them to you at the lowest prices all year round.</p>\n\n<p>Unlike other online retailers,&nbsp;<a href=\"https://www.mandmdirect.com/01/landing/blog-181203-voucher-codes\">we&nbsp;<strong>don&#39;t</strong>&nbsp;do discount codes or promotions</a>&nbsp;- just your favourite brands all with up to 75% off the RRP.</p>\n\n<p>Trustpilot is a digital review platform that focuses on inspiring trust &amp; collaboration, whilst also helping consumers shop with confidence. Since its founding in 2007, Trustpilot now has over 120 million consumer reviews.</p>\n\n<p>At MandM Direct, we have been collecting reviews and currently hold a strong 4.3/5 star rating on Trustpilot - based on over 8,000 reviews!</p>\n\n<p>Take a closer look at what some of our happy customers are saying below...</p>\n\n<h1>Our name</h1>\n\n<p>&#39;MM Direct&#39;, &#39;mnm&#39;, &#39;mdirect&#39;, &#39;mandm sports&#39; - trust us, we&#39;ve heard them all!</p>\n\n<p><strong>MandM Direct</strong>&nbsp;originates from the first names of our founders (the &#39;two Ms&#39;). So MandM stands for&nbsp;<strong>M</strong>ark&nbsp;<strong>and</strong>&nbsp;<strong>M</strong>artin&nbsp;<strong>Direct!</strong></p>\n\n<p>We&#39;re also proud to have our name associated with good causes and have a longstanding partnership with&nbsp;<strong>Teenage Cancer Trust</strong>&nbsp;since 2005. Since then, with your support, we&#39;ve managed to&nbsp;<strong>raise over &pound;2 million</strong>&nbsp;that has gone directly towards improving the quality of life and chances of survival for young people with cancer aged between 13 and 24.</p>\n\n<p>Find out more about&nbsp;<a href=\"https://www.mandmdirect.com/01/landing/teenagecancertrust\">our partnership with Teenage Cancer Trust</a>.</p>\n\n<p><img alt=\"Our Partnership With Teenage Cancer Trust\" src=\"https://www.mandmdirect.com/assets/images/mmv-637419781020000000/landingPages/about/about-tct-1.jpg\" style=\"height:auto\" /></p>\n\n<h1>COMPANY HISTORY</h1>\n\n<table cellspacing=\"0\" style=\"border-collapse:collapse; width:1160px\">\n	<tbody>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">1987</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">MandM Direct Founded</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">1991</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Started trading as MandM Sports Ltd.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">1998</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">MandMSports.co.uk launches.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2004</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Management buy-out led by Mike Tomkins in partnership with ECI Partners LLP.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2005</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">The company is re-branded as MandM Direct Ltd to reflect our fashion, sport and outdoor offer.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2005</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Started our long term partnership with Teenage Cancer Trust.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2007</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Won Consumer Category for Outdoor Pursuits, Sports at the ECMOD Awards. TA Associates take controlling stake in MandM Direct and Mike Tomkins becomes the Non-Exec Chairman.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2008</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Awarded 2nd place in Sunday Times Fast Track.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2009</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">MRG/Hitwise Top 100 Award winner for 2009 - Clothing, Apparel and sportswear.<br />\n			Reached over &pound;600,000 raised for Teenage Cancer Trust.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2010</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Won Drapers Etailer of the Year, Drapers Best Etail Marketing Initiative and Drapers Best Pure-Play Etailer.<br />\n			Won BT Retail Week Technology Award.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2012</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">The company celebrated its 25th Anniversary.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2013</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Reached &pound;1 million fundraising for Teenage Cancer Trust.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2014</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">MandM Direct became part of BESTSELLER UNITED A/S, and revenues surpassed &pound;120 million.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2014</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Winner of the Best Mobile Site Retail Week award.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2015</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Reached 95% satisfaction rating on Feefo.<br />\n			Voted 4th best Clothing, Shoes and Accessories website in the November 2015 edition of Which? Magazine.<br />\n			MandM Direct celebrate 10 years of supporting Teenage Cancer Trust.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2017</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">&pound;1.5 million raised for Teenage Cancer Trust.<br />\n			The company celebrated its 30th Anniversary.<br />\n			Highly commended in Men&#39;s Running and Women&#39;s Running magazine readers awards for best retailer.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2018</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Reached 2 million happy customers.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2020</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Achieved Feefo&#39;s Platinum Trusted Status for maintaining three consecutive years of Gold Standard.</td>\n		</tr>\n		<tr>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2020</td>\n			<td style=\"background-color:#f9f9f9; border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Reached 3 million happy customers.</td>\n		</tr>\n		<tr>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">2020</td>\n			<td style=\"border-top:1px solid #dddddd; text-align:left; vertical-align:top\">Over &pound;2 million raised for Teenage Cancer Trust.</td>\n		</tr>\n	</tbody>\n</table>\n', 1);

