-- Table structure for vs_comment
-- ----------------------------
DROP TABLE IF EXISTS `vs_comment`;
CREATE TABLE `vs_comment`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `vehicle_id` int NULL DEFAULT NULL,
  `comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `user_id` int NULL DEFAULT NULL,
  `time_posted` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date_posted` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `vehicle_fk`(`vehicle_id`) USING BTREE,
  INDEX `user_fk`(`user_id`) USING BTREE,
  CONSTRAINT `user_fk` FOREIGN KEY (`user_id`) REFERENCES `vs_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vehicle_fk` FOREIGN KEY (`vehicle_id`) REFERENCES `vs_vehicle_details` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

