DROP TABLE IF EXISTS `vs_email_templates`;
CREATE TABLE `vs_email_templates`  (
  `account_registration_activation_link` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `successful_activation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `change_of_email_activation_link` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `success_email_change_new` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `success_email_change_old` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `change_password_activation_link` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `success_password_change` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `vehicle_additions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `vehicle_modifications` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `user_request` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `receipt_of_user_request` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `account_blockage` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `admin_changes_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `decision_on_user_request` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `daily_report` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

