INSERT INTO `vs_email_templates` VALUES ('<p>[username]<strong> Your registration has been successfully completed. Kindly click the link to activate your account</strong>&nbsp;[activation_link] .</p>', '<p>[username]<strong> your account has been successfully activated.</strong></p>', '<p><strong>Kindly click the link to activate your email</strong>&nbsp;[activation_link] .</p>', '<p>[username]<strong> your email has been successfully changed.</strong></p>', '<p>[username]<strong> your account has been successfully changed.</strong></p>', '<p>klk;l,;</p>', NULL, '<p>Hello [username],&nbsp; information on addition of vehicle.</p>\n\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:800px\">\n	<thead>\n		<tr>\n			<th scope=\"col\">Date</th>\n			<th scope=\"col\">Time of addition</th>\n			<th scope=\"col\">Type</th>\n			<th scope=\"col\">Brand</th>\n			<th scope=\"col\">Year of Production</th>\n		</tr>\n	</thead>\n	<tbody>\n		<tr>\n			<td>[curr_date]</td>\n			<td>[time_of_addition]</td>\n			<td>[type]</td>\n			<td>[brand]</td>\n			<td>[year_of_production]</td>\n		</tr>\n	</tbody>\n</table>', '<p>Hello [username],&nbsp; information on vehicle modification.</p>\n\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:800px\">\n	<thead>\n		<tr>\n			<th scope=\"col\">Date</th>\n			<th scope=\"col\">Time of addition</th>\n			<th scope=\"col\">Type</th>\n			<th scope=\"col\">Brand</th>\n			<th scope=\"col\">Year of Production</th>\n		</tr>\n	</thead>\n	<tbody>\n		<tr>\n			<td>[curr_date]</td>\n			<td>[time_of_addition]</td>\n			<td>[type]</td>\n			<td>[brand]</td>\n			<td>[year_of_production]</td>\n		</tr>\n	</tbody>\n</table>', NULL, NULL, '<p>[username]<strong> your account has been blocked.</strong></p>', NULL, NULL, NULL);

