-- Table structure for vs_inbox
-- ----------------------------
DROP TABLE IF EXISTS `vs_inbox`;
CREATE TABLE `vs_inbox`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NULL DEFAULT NULL,
  `receiver_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `sender_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

