-- ----------------------------
-- Table structure for vs_messages
-- ----------------------------
DROP TABLE IF EXISTS `vs_messages`;
CREATE TABLE `vs_messages`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `sender_id` int NULL DEFAULT NULL,
  `receiver_id` int NULL DEFAULT NULL,
  `message` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date_posted` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `time_posted` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `read_msg` int NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `message_fkk`(`sender_id`) USING BTREE,
  CONSTRAINT `message_fkk` FOREIGN KEY (`sender_id`) REFERENCES `vs_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 214 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of vs_messages
-- ----------------------------

