-- ----------------------------
-- View structure for vw_about
-- ----------------------------
DROP VIEW IF EXISTS `vw_about`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_about` AS select `vs_about`.`about` AS `about`,`vs_about`.`id` AS `id` from `vs_about`; ;

-- ----------------------------
-- View structure for vw_advertisement_left
-- ----------------------------
DROP VIEW IF EXISTS `vw_advertisement_left`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_advertisement_left` AS select `vs_advertisement_left`.`id` AS `id`,`vs_advertisement_left`.`homepage_left_ad` AS `homepage_left_ad`,`vs_advertisement_left`.`vehicle_details_left_ad` AS `vehicle_details_left_ad`,`vs_advertisement_left`.`gallery_left_ad` AS `gallery_left_ad`,`vs_advertisement_left`.`advertising_left_link` AS `advertising_left_link`,`vs_advertisement_left`.`ad_state` AS `ad_state`,`vs_advertisement_left`.`logged_in_user_ad_state` AS `logged_in_user_ad_state`,`vs_advertisement_left`.`type_of_ad` AS `type_of_ad` from `vs_advertisement_left`; ;

-- ----------------------------
-- View structure for vw_advertisement_right
-- ----------------------------
DROP VIEW IF EXISTS `vw_advertisement_right`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_advertisement_right` AS select `vs_advertisement_right`.`id` AS `id`,`vs_advertisement_right`.`homepage_right_ad` AS `homepage_right_ad`,`vs_advertisement_right`.`vehicle_details_right_ad` AS `vehicle_details_right_ad`,`vs_advertisement_right`.`gallery_right_ad` AS `gallery_right_ad`,`vs_advertisement_right`.`advertising_right_link` AS `advertising_right_link`,`vs_advertisement_right`.`ad_state` AS `ad_state`,`vs_advertisement_right`.`logged_in_user_ad_state` AS `logged_in_user_ad_state`,`vs_advertisement_right`.`type_of_ad` AS `type_of_ad` from `vs_advertisement_right`; ;

-- ----------------------------
-- View structure for vw_comment
-- ----------------------------
DROP VIEW IF EXISTS `vw_comment`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_comment` AS select `c`.`id` AS `id`,`c`.`vehicle_id` AS `vehicle_id`,`c`.`comment` AS `comment`,`c`.`user_id` AS `user_id`,`c`.`time_posted` AS `time_posted`,`c`.`date_posted` AS `date_posted`,`u`.`username` AS `username`,`u`.`avatar` AS `avatar` from (`vs_comment` `c` left join `vs_user` `u` on(`u`.`id` = `c`.`user_id`)); ;

-- ----------------------------
-- View structure for vw_contact_form
-- ----------------------------
DROP VIEW IF EXISTS `vw_contact_form`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_contact_form` AS select `cf`.`id` AS `id`,`cf`.`username` AS `username`,`cf`.`email` AS `email`,`cf`.`subject` AS `subject`,`cf`.`message` AS `message`,`cf`.`user_id` AS `user_id`,`cf`.`read_msg` AS `read_msg`,`cf`.`login_status` AS `login_status`,`cf`.`date_posted` AS `date_posted`,`cf`.`time_posted` AS `time_posted`,`cf`.`admin_id` AS `admin_id`,`u`.`user_activity` AS `user_activity`,`u`.`avatar` AS `avatar` from (`vs_contact_form` `cf` left join `vs_user` `u` on(`u`.`id` = `cf`.`user_id`)); ;

-- ----------------------------
-- View structure for vw_dr_blocked
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_blocked`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_blocked` AS select `vs_user`.`blocked_date` AS `blocked_date`,`vs_user`.`username` AS `username`,`vs_user`.`blocked_time` AS `blocked_time` from `vs_user` where `vs_user`.`blocked_date` = curdate(); ;

-- ----------------------------
-- View structure for vw_dr_change_email
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_change_email`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_change_email` AS select `vs_user`.`change_email_date` AS `change_email_date`,`vs_user`.`username` AS `username`,`vs_user`.`change_email_time` AS `change_email_time`,`vs_user`.`email` AS `email`,`vs_user`.`old_email` AS `old_email` from `vs_user` where `vs_user`.`change_email_date` = curdate(); ;

-- ----------------------------
-- View structure for vw_dr_change_password
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_change_password`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_change_password` AS select `vs_user`.`change_password_date` AS `change_password_date`,`vs_user`.`username` AS `username`,`vs_user`.`change_password_time` AS `change_password_time` from `vs_user` where `vs_user`.`change_password_date` = curdate(); ;

-- ----------------------------
-- View structure for vw_dr_new_user
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_new_user`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_new_user` AS select `vs_user`.`date_of_registration` AS `date_of_registration`,`vs_user`.`username` AS `username`,`vs_user`.`time_of_registration` AS `time_of_registration`,`vs_user`.`email` AS `email` from `vs_user` where `vs_user`.`date_of_registration_report` = utc_date(); ;

-- ----------------------------
-- View structure for vw_dr_vehicle_addition
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_vehicle_addition`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_vehicle_addition` AS select `v`.`date_added` AS `date_added`,`v`.`time_added` AS `time_added`,`v`.`brand` AS `brand`,`u`.`username` AS `username` from (`vs_vehicle_details` `v` left join `vs_user` `u` on(`u`.`id` = `v`.`user_id`)) where `v`.`date_added` = curdate(); ;

-- ----------------------------
-- View structure for vw_dr_vehicle_modification
-- ----------------------------
DROP VIEW IF EXISTS `vw_dr_vehicle_modification`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_dr_vehicle_modification` AS select `v`.`last_modification` AS `last_modification`,`v`.`brand` AS `brand`,`u`.`username` AS `username` from (`vs_vehicle_details` `v` left join `vs_user` `u` on(`u`.`id` = `v`.`user_id`)) where `v`.`last_modification_report` = curdate(); ;

-- ----------------------------
-- View structure for vw_email_templates
-- ----------------------------
DROP VIEW IF EXISTS `vw_email_templates`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_email_templates` AS select `vs_email_templates`.`account_registration_activation_link` AS `account_registration_activation_link`,`vs_email_templates`.`successful_activation` AS `successful_activation`,`vs_email_templates`.`change_of_email_activation_link` AS `change_of_email_activation_link`,`vs_email_templates`.`success_email_change_new` AS `success_email_change_new`,`vs_email_templates`.`success_email_change_old` AS `success_email_change_old`,`vs_email_templates`.`change_password_activation_link` AS `change_password_activation_link`,`vs_email_templates`.`success_password_change` AS `success_password_change`,`vs_email_templates`.`vehicle_additions` AS `vehicle_additions`,`vs_email_templates`.`vehicle_modifications` AS `vehicle_modifications`,`vs_email_templates`.`user_request` AS `user_request`,`vs_email_templates`.`receipt_of_user_request` AS `receipt_of_user_request`,`vs_email_templates`.`account_blockage` AS `account_blockage`,`vs_email_templates`.`admin_changes_list` AS `admin_changes_list`,`vs_email_templates`.`decision_on_user_request` AS `decision_on_user_request`,`vs_email_templates`.`daily_report` AS `daily_report` from `vs_email_templates`; ;

-- ----------------------------
-- View structure for vw_messages
-- ----------------------------
DROP VIEW IF EXISTS `vw_messages`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_messages` AS select `vs_messages`.`id` AS `id`,`vs_messages`.`sender_id` AS `sender_id`,`vs_messages`.`receiver_id` AS `receiver_id`,`vs_messages`.`message` AS `message`,`vs_messages`.`date_posted` AS `date_posted`,`vs_messages`.`time_posted` AS `time_posted`,`vs_messages`.`read_msg` AS `read_msg`,`u`.`username` AS `sender_username`,`s`.`username` AS `receiver_username`,`s`.`avatar` AS `receiver_avatar`,`u`.`email` AS `sender_email`,`u`.`avatar` AS `sender_avatar`,`u`.`status` AS `sender_status` from ((`vs_messages` left join `vs_user` `u` on(`vs_messages`.`sender_id` = `u`.`id`)) left join `vs_user` `s` on(`vs_messages`.`receiver_id` = `s`.`id`)); ;

-- ----------------------------
-- View structure for vw_news
-- ----------------------------
DROP VIEW IF EXISTS `vw_news`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_news` AS select `vs_news`.`id` AS `id`,`vs_news`.`news` AS `news`,`vs_news`.`heading` AS `heading` from `vs_news`; ;

