-- ----------------------------
DROP VIEW IF EXISTS `vw_select_list`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_select_list` AS select `vs_select_list`.`brand` AS `brand`,`vs_select_list`.`model` AS `model`,`vs_select_list`.`type_of_vehicle` AS `type_of_vehicle`,`vs_select_list`.`fuel_type` AS `fuel_type`,`vs_select_list`.`no_of_doors` AS `no_of_doors`,`vs_select_list`.`no_of_seats` AS `no_of_seats`,`vs_select_list`.`transmission` AS `transmission`,`vs_select_list`.`drive` AS `drive`,`vs_select_list`.`subject` AS `subject`,`vs_select_list`.`location` AS `location`,`vs_select_list`.`country_of_origin` AS `country_of_origin` from `vs_select_list`; ;

-- ----------------------------
-- View structure for vw_slider_config
-- ----------------------------
DROP VIEW IF EXISTS `vw_slider_config`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_slider_config` AS select `vs_slider_config`.`id` AS `id`,`vs_slider_config`.`image` AS `image`,`vs_slider_config`.`line_one` AS `line_one`,`vs_slider_config`.`line_two` AS `line_two`,`vs_slider_config`.`font_size` AS `font_size`,`vs_slider_config`.`font_color` AS `font_color` from `vs_slider_config`; ;

